insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('CL', 'default', 'Plan de cuentas Ekwo para Chile (sin catálogo oficial)', '{}'::jsonb, true, 'companies', array['CL-BAL', 'CL-RES']::text[], null, 'Chile no fija por ley un plan de cuentas: el Código Tributario, art. 17, sólo exige llevar «contabilidad fidedigna» en los libros que el Servicio de Impuestos Internos autoriza, sin imponer códigos ni nombres de cuenta — a diferencia del código agrupador que el Anexo 24 de la RMF mexicana publica. Este plan es una numeración propia de Ekwo (clases 1 a 5, sin correlato oficial), pensada para que cada cuenta alcance una línea del Estado de Situación Financiera y del Estado de Resultados del artículo 74 de la Ley N° 18.046. Una empresa puede llevar cualquier otro plan de cuentas: éste es el que Ekwo instala por defecto', 'dl825')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

