   applies_supply_vs_seller)
values
  ('CL', 'CL-P-19-BIENES', 'Compras de bienes, tasa general 19 %', '{}'::jsonb, 'Adquisición de bienes corporales muebles del giro, con derecho a crédito fiscal', 'percent', 19, 'purchase', 'domestic', date '1975-01-01', null, 'Decreto Ley N° 825, art. 14 — tasa de 19 %; art. 23 — «Los contribuyentes afectos al pago del tributo de este Título tendrán derecho a un crédito fiscal… equivalente al impuesto de este Título recargado en las facturas que acrediten sus adquisiciones». Formulario 29, línea 28 (Cód. 519/520): «Facturas recibidas del giro y Facturas de compra emitidas, con derecho a crédito fiscal»', 'S', null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'dl825', null, null, null, null),
  ('CL', 'CL-P-19-SERVICIOS', 'Compras de servicios, tasa general 19 %', '{}'::jsonb, 'Servicio recibido del giro, con derecho a crédito fiscal, acreditable al pagarse', 'percent', 19, 'purchase', 'domestic', date '1975-01-01', null, 'Decreto Ley N° 825, art. 14 y art. 23 — mismo derecho a crédito fiscal que CL-P-19-BIENES; art. 9°, letra a), y art. 55, inciso tercero — el proveedor del servicio devenga y factura su IVA al percibir o disponer de la remuneración, de modo que el crédito fiscal del comprador nace en esa misma fecha. Se declara cash_basis, sobre la cuenta de tránsito 1106, por la razón dada en CL-S-19-SERVICIOS', 'S', null, 70, 'vat', true, '{}'::tax_condition[], null, false, true, '1106', 'dl825', null, null, null, null),
  ('CL', 'CL-P-FSR-19', 'Servicio recibido de un prestador domiciliado en el extranjero', '{}'::jsonb, 'El beneficiario del servicio, contribuyente de este impuesto, es el sujeto pasivo cuando el prestador no está domiciliado ni reside en Chile', 'percent', 19, 'purchase', 'foreign_services_received', date '1975-01-01', null, 'Decreto Ley N° 825, art. 11, letra e) — son sujetos del impuesto «el beneficiario del servicio que sea contribuyente de este impuesto, siempre que la prestación sea realizada por un prestador domiciliado o residente en el extranjero»; art. 10, inciso segundo, y art. 5° — el servicio se entiende prestado en Chile cuando la actividad que lo genera se desarrolla en Chile, cualquiera sea el lugar donde se utilice, o cuando se usa en Chile aunque la remuneración se pague en el extranjero. El beneficiario se autofactura el débito y, al mismo tiempo, el crédito fiscal de la misma operación (art. 23), por lo que el efecto neto en la declaración es nulo salvo que el gasto sea sólo parcialmente afecto a IVA en manos del beneficiario. No hay categoría EN 16931 que registrar (ningún comprobante del prestador extranjero está gobernado por esa norma) ni código de exención, porque la operación no es una exención sino un traslado de la calidad de sujeto del impuesto', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'dl825', null, null, null, null),
  ('CL', 'CL-S-0-EXP-BIENES', 'Exportación de bienes', '{}'::jsonb, 'Especies exportadas en su venta al exterior', 'percent', 0, 'sale', 'export', date '1975-01-01', null, 'Decreto Ley N° 825, art. 12, letra D — «Estarán exentas del impuesto establecido en este Título: … D.- Las especies exportadas en su venta al exterior». El exportador no traslada IVA en la exportación y, en cambio, tiene derecho a recuperar el impuesto soportado en sus compras e importaciones destinadas a esa actividad conforme al art. 36 — véase CL-P-19-BIENES y CL-P-19-SERVICIOS, que dan ese crédito, y la línea 37 (Cód. 593) del Formulario 29, que declara la devolución solicitada por el art. 36. La aduana certifica la salida de las especies (Documento Único de Salida)', 'G', null, 30, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'dl825', null, null, null, null),
  ('CL', 'CL-S-0-EXP-SERVICIOS', 'Exportación de servicios', '{}'::jsonb, 'Servicios prestados a personas sin domicilio ni residencia en Chile, calificados como exportación por el Servicio Nacional de Aduanas', 'percent', 0, 'sale', 'export', date '1975-01-01', null, 'Decreto Ley N° 825, art. 12, letra E, N° 16 — «Los ingresos percibidos por la prestación de servicios a personas sin domicilio ni residencia en Chile, siempre que el Servicio Nacional de Aduanas califique dichos servicios como exportación… La exención procederá respecto de aquellos servicios que sean prestados total o parcialmente en Chile para ser utilizados en el extranjero»; art. 36, inciso cuarto — los prestadores de estos servicios gozan del mismo derecho a recuperar el IVA soportado que un exportador de bienes', 'G', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'dl825', null, null, null, null),
  ('CL', 'CL-S-19-BIENES', 'Ventas de bienes, tasa general 19 %', '{}'::jsonb, 'Venta de bienes corporales muebles gravada a la tasa general', 'percent', 19, 'sale', 'domestic', date '1975-01-01', null, 'Decreto Ley N° 825, art. 14 — «Los contribuyentes afectos a las disposiciones del presente Título pagarán el impuesto con una tasa de 19 % sobre la base imponible»; art. 8° — hecho gravado; art. 2° N° 1° — definición de «venta». El devengo sigue la regla general de tax_point (delivery_date): el art. 9°, letra a), fija el devengo en la fecha de la factura, salvo que la entrega sea anterior, y el art. 55 exige que la factura de una venta de bienes se emita «en el mismo momento» de la entrega real o simbólica de las especies, de modo que ambas fechas coinciden en el caso regular', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'dl825', null, null, null, null),
  ('CL', 'CL-S-19-SERVICIOS', 'Prestaciones de servicios, tasa general 19 %', '{}'::jsonb, 'Servicio gravado a la tasa general, devengado al percibirse o ponerse a disposición la remuneración', 'percent', 19, 'sale', 'domestic', date '1975-01-01', null, 'Decreto Ley N° 825, art. 14 — tasa de 19 %; art. 8° — hecho gravado; art. 2° N° 2° — definición de «servicio». Devengo: art. 9°, letra a) — en las prestaciones de servicios el impuesto se devenga en la fecha de emisión de la factura o boleta y, si no se hubieren emitido, «en cualquier forma, a disposición del prestador del servicio»; art. 55, inciso tercero — la factura de un servicio «deberá emitirse en el mismo periodo tributario en que la remuneración se perciba o se ponga, en cualquier forma, a disposición del prestador del servicio», de modo que el devengo de un servicio coincide con su cobro. Este paquete lo declara cash_basis, sobre la cuenta de tránsito 2104, porque el formato fija un solo tax_point por país (delivery_date, que sigue el caso general de los bienes) y reserva cash_basis para la regla distinta de un tipo de operación — el mismo mecanismo que usa el paquete de Francia para sus servicios', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, true, '2104', 'dl825', null, null, null, null),
  ('CL', 'CL-S-EXE-EDU', 'Ingresos de establecimientos de educación', '{}'::jsonb, 'Ingresos por la actividad docente propiamente tal de un establecimiento de educación', 'percent', 0, 'sale', 'exempt', date '1975-01-01', null, 'Decreto Ley N° 825, art. 13 — «Estarán liberadas del impuesto de este Título las siguientes empresas e instituciones: … 4.- Los establecimientos de educación. Esta exención se limitará a los ingresos que perciban en razón de su actividad docente propiamente tal»', 'E', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'dl825', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
