insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('CL', 'CL-F29-IVA', 'Formulario 29 — Declaración Mensual y Pago Simultáneo de Impuestos, sección Impuesto al Valor Agregado', array['month']::declaration_period[], 'month'::declaration_period, date '1975-01-01', null, 'Decreto Ley N° 825, art. 64, inciso primero — «Los contribuyentes afectos a la presente ley deberán pagar en la Tesorería Comunal respectiva, o en las oficinas bancarias autorizadas por el Servicio de Tesorerías, hasta el día 12 de cada mes, los impuestos devengados en el mes anterior… En el mismo acto deberán presentar una declaración jurada del monto total de las operaciones realizadas en el mes anterior, incluso las exentas de impuesto». Los campos son los códigos del Formulario 29, versión Internet, sección «Impuesto al Valor Agregado D.L. 825/74»; este paquete transcribe sólo los campos que el Impuesto al Valor Agregado alimenta y omite los de los demás tributos y regímenes que declara el mismo formulario (impuesto adicional a las ventas, cambio de sujeto, retenciones de la Ley de la Renta y pagos provisionales mensuales) — véase «Lo que este paquete no transcribe» en el README', true,'day_of_month_after_period'::filing_deadline_rule, 12, null, 'Decreto Ley N° 825, art. 64, inciso primero — pago hasta el día 12 del mes siguiente al de la operación. Un contribuyente que declara y paga por Internet obtiene, por resolución administrativa del Servicio de Impuestos Internos y no por esta ley, una prórroga hasta el día 20 (con pago) o el día 28 (sin pago) del mismo mes; este paquete declara el día que la ley fija a todo contribuyente, no la prórroga condicionada al canal de declaración', 'f29-plazos', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
