values
  ('CL', 'CL-F29-IVA', '20', 'base', 'Exportaciones (monto neto)', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formulario 29, línea 1: «Exportaciones» — Cód. 585 (cantidad de documentos de exportación), Cód. 20 (monto neto contenido en los documentos registrados en el Cód. 585)', 'f29-formulario'),
  ('CL', 'CL-F29-IVA', '142', 'base', 'Ventas y/o servicios prestados exentos, o no gravados del giro (monto neto)', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formulario 29, línea 2: «Ventas y/o Servicios prestados Exentos, o No Gravados del giro» — Cód. 586 (cantidad de documentos), Cód. 142 (monto neto de los documentos registrados en el Cód. 586)', 'f29-formulario'),
  ('CL', 'CL-F29-IVA', '502', 'tax', 'Débito fiscal — facturas emitidas por ventas y servicios del giro', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formulario 29, línea 7: «Facturas emitidas por ventas y servicios del giro, o por cuenta de terceros» — Cód. 503 (cantidad de facturas emitidas durante el período), Cód. 502 (monto del impuesto recargado en las facturas registradas en el Cód. 503)', 'f29-instrucciones'),
  ('CL', 'CL-F29-IVA', '538', 'total', 'Total débitos', '{}'::jsonb, 40, null, array['502']::text[], '{}'::text[], null, null, false, false, null, 'Formulario 29, línea 23: «Registre el valor que resulte de realizar la operación aritmética de los montos de la línea 7 a 22» — este paquete suma únicamente el Cód. 502, la única línea de esa sección que sus impuestos alimentan', 'f29-instrucciones'),
  ('CL', 'CL-F29-IVA', '520', 'tax', 'Crédito fiscal — facturas recibidas del giro', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formulario 29, línea 28: «Facturas recibidas del giro y Facturas de compra emitidas» — Cód. 519 (cantidad de facturas recibidas durante el período, por adquisición de bienes o utilización de servicios que dan derecho a crédito fiscal), Cód. 520 (monto de crédito fiscal recargado en las facturas registradas en el Cód. 519)', 'f29-formulario'),
  ('CL', 'CL-F29-IVA', '537', 'total', 'Total créditos', '{}'::jsonb, 60, null, array['520']::text[], '{}'::text[], null, null, false, false, null, 'Formulario 29, línea 49: «Registre el valor que resulte de realizar la operación aritmética de los montos de la línea 28 a 48» — este paquete suma únicamente el Cód. 520, la única línea de esa sección que sus impuestos alimentan', 'f29-instrucciones'),
  ('CL', 'CL-F29-IVA', '89', 'total', 'Impuesto determinado (IVA a pagar)', '{}'::jsonb, 70, null, array['538']::text[], array['537']::text[], null, null, true, false, null, 'Formulario 29, línea 50, Cód. 89 — el resultado positivo de restar el Total de Créditos (Cód. 537) del Total de Débitos (Cód. 538) es el impuesto determinado del período', 'f29-formulario'),
  ('CL', 'CL-F29-IVA', '77', 'total', 'Remanente de crédito fiscal para el período siguiente', '{}'::jsonb, 80, null, array['537']::text[], array['538']::text[], null, null, true, false, null, 'Formulario 29, línea 50, Cód. 77 — cuando el Total de Créditos (Cód. 537) excede al Total de Débitos (Cód. 538), la diferencia es el remanente de crédito fiscal que el art. 26 del D.L. N° 825 acumula a los créditos del período tributario siguiente', 'f29-formulario')
