insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('CL-BAL', 'CL', 'default', 'Estado de Situación Financiera', 'balance_sheet', 'CL-Ekwo', date '1970-01-01', null, 'Ley N° 18.046, sobre Sociedades Anónimas, art. 74 — el directorio presenta anualmente a la junta ordinaria de accionistas «una memoria razonada acerca de la situación de la sociedad en el último ejercicio, acompañada del balance general, del estado de ganancias y pérdidas», que «deberán reflejar con claridad la situación patrimonial de la sociedad al cierre del ejercicio y los beneficios obtenidos o las pérdidas sufridas durante el mismo». Chile no fija un plan de cuentas ni una estructura de líneas obligatoria para ese balance fuera de las sociedades que la Comisión para el Mercado Financiero fiscaliza (que reportan bajo Normas Internacionales de Información Financiera, cuyo texto no se transcribe aquí): esta es la estructura mínima que Ekwo instala por defecto, agrupada por naturaleza (activo circulante, activo fijo, pasivo circulante, pasivo no corriente, patrimonio), sobre el plan de cuentas propio del paquete', 'ley18046'),
  ('CL-RES', 'CL', 'default', 'Estado de Resultados', 'income_statement', 'CL-Ekwo', date '1970-01-01', null, 'Ley N° 18.046, sobre Sociedades Anónimas, art. 74 — el balance general se acompaña del «estado de ganancias y pérdidas» que refleja «los beneficios obtenidos o las pérdidas sufridas» del ejercicio. Estructura mínima propia de Ekwo, con los subtotales de utilidad bruta, operacional, antes de impuesto y neta', 'ley18046')
