update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{NNNN}',
  legal_payment_days            = 30,
  late_payment_reference        = 'Ley N° 21.131, que establece un plazo máximo de 30 días corridos desde la recepción de la factura para su pago, salvo pacto escrito en contrario que cumpla los requisitos legales; desde el primer día de mora se aplica el interés corriente para operaciones no reajustables en moneda nacional (según el monto y plazo de la operación) más una comisión fija de recuperación de pago del 1 % del saldo insoluto (art. 2° bis de la ley, que incorpora los arts. 2 bis y siguientes a la Ley N° 19.983)',
  numbering_legal_reference     = 'Decreto Ley N° 825, art. 54 — los documentos tributarios (facturas, boletas, guías de despacho, notas de débito y de crédito) son documentos electrónicos con «folio» dentro de un «Código de Autorización de Folios» (CAF) que el Servicio de Impuestos Internos autoriza previamente por rangos, correlativo por tipo de documento y no reiniciado cada año. El folio de un CAF lo asigna y usa el propio emisor dentro del rango autorizado — no es asignado documento a documento por el Servicio, a diferencia del folio fiscal (UUID) del CFDI mexicano. El número que declara este paquete es el de la pieza contable, correlativo por diario, y no un folio de un CAF que Ekwo no solicita: véase «Ekwo no emite un DTE chileno» en el README',
  numbering_source_key          = 'dl825',
  payment_terms_legal_reference = 'Ley N° 21.131, de 2019 (D.O. 16.01.2019, vigencia 17.05.2019), que modifica la Ley N° 19.983: plazo máximo de pago de 30 días corridos desde la recepción de la factura, salvo acuerdo escrito excepcional entre las partes que cumpla los requisitos legales (identificación de las partes, giro, fecha, plazo, vigencia, inscripción en el Registro de Acuerdos de Pago del Ministerio de Economía dentro de 5 días hábiles) y no constituya una cláusula abusiva',
  payment_terms_source_key      = 'ley21131',
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Decreto Ley N° 825, art. 9°, letra a) — «El impuesto establecido en este Título se devengará: a) En las ventas de bienes corporales muebles y prestaciones de servicios, en la fecha de emisión de la factura o boleta. En la venta de bienes corporales muebles, en caso que la entrega de las especies sea anterior a dicha fecha o bien, cuando por la naturaleza del acto que da origen a la transferencia no se emitan dichos documentos, el impuesto se devengará en la fecha de la entrega real o simbólica de las especies. En las prestaciones de servicios, si no se hubieren emitido facturas o boletas, según corresponda, o no correspondiere emitirlas, el tributo se devengará, en cualquier forma, a disposición del prestador del servicio». El art. 55 exige que, en la venta de bienes, la factura se emita «en el mismo momento» de la entrega, de modo que factura y entrega coinciden salvo mora del emisor — caso en que la entrega, más temprana, sigue fijando el devengo: por eso este paquete declara delivery_date como regla general, igual que Francia. En los servicios el art. 55 exige la factura «en el momento en que se perciba o se ponga, en cualquier forma, a disposición del prestador del servicio» la remuneración, de modo que el devengo de un servicio coincide con su cobro: los códigos de impuesto de servicios de este paquete llevan cash_basis, con la cuenta de tránsito que exige ese campo, en vez de un segundo valor de tax_point que el formato no admite',
  tax_point_source_key          = 'dl825',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Decreto Ley N° 825, arts. 21 N° 2° y 57 — un débito fiscal facturado en exceso, o una venta o servicio resciliado, anulado o devuelto, se corrige con una nota de crédito que individualiza el documento que rectifica, nunca con la modificación del documento original; el art. 29-A del Código Fiscal (por analogía con el criterio del Servicio) y el propio DTE, una vez con folio de un CAF y enviado, no admiten edición. Ekwo no emite folios de un CAF (véase el README), pero conserva la misma regla: un documento contabilizado se corrige con un comprobante de egreso (nota de crédito) que lo nombra',
  posted_edit_policy_source_key = 'dl825',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Decreto Ley N° 825, art. 54, y art. 54, incisos siguientes (según los sustituyó la Ley N° 20.727, D.O. 31.01.2014) — las facturas, facturas de compra, guías de despacho, boletas, liquidaciones-factura y notas de débito y de crédito se emiten exclusivamente como documentos tributarios electrónicos (DTE), con folio de un Código de Autorización de Folios (CAF) que el Servicio de Impuestos Internos autoriza por rangos, timbre electrónico del emisor y envío del documento al Servicio dentro del plazo que fija la resolución respectiva. La obligatoriedad se implementó de forma escalonada según tamaño de la empresa desde noviembre de 2014 y alcanzó a todas las empresas del país el 1 de febrero de 2018 («A partir de hoy todas las empresas del país deben facturar electrónicamente», noticia SII del 01.02.2018): desde esa fecha, un documento en papel «no tendrá validez legal». Es un régimen de autorización previa de folios y envío al Servicio (más próximo a un reporte continuo de operaciones que a la validación documento a documento de un tercero certificador, como el PAC mexicano) y no un intercambio entre empresas gobernado por un perfil construido sobre EN 16931. EKWO NO SOLICITA CAF, NO TIMBRA NI TRANSMITE DTE: ningún componente de packages/formats emite el XML del DTE chileno ni se comunica con el Servicio de Impuestos Internos, y un documento emitido desde Ekwo no es un comprobante tributario chileno. Por eso profile, mandatory_from y party_scheme/vat_scheme quedan vacíos aunque la obligación exista: profile nombra un perfil construido sobre EN 16931 que una pieza de packages/formats escribe, el DTE no lo es, y el formato refuse un mandatory_from sin profile. El Rol Único Tributario (RUT) identifica a emisor y receptor y no tiene código ISO 6523 de la lista que el formato usa para party_scheme y vat_scheme',
  einvoice_source_key           = 'ley20727',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = array['csv']::text[],
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'CL';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('CL', 'dte_not_issued', 'always', 'Este documento no es un Documento Tributario Electrónico (DTE) chileno: no lleva folio de un Código de Autorización de Folios (CAF) del Servicio de Impuestos Internos ni su timbre electrónico. Sólo el DTE con folio de un CAF ampara la operación para efectos tributarios en Chile.', '{}'::jsonb, 10, date '1970-01-01', null, 'Decreto Ley N° 825, art. 54, y art. 54, incisos siguientes, sobre la exigencia de que los documentos tributarios sean documentos electrónicos con folio de un CAF autorizado por el Servicio de Impuestos Internos; Ley N° 20.727. Ekwo no solicita CAF, no timbra ni transmite DTE: la frase evita que el documento que Ekwo produce se tome por el comprobante fiscal chileno'),
  ('CL', 'export', 'export', 'Exportación — venta o servicio exento del Impuesto al Valor Agregado (artículo 12, letra D, o letra E, N° 16, del D.L. N° 825, de 1974).', '{}'::jsonb, 20, date '1970-01-01', null, 'Decreto Ley N° 825, art. 12, letra D («Las especies exportadas en su venta al exterior») y letra E, N° 16 (ingresos por servicios prestados a personas sin domicilio ni residencia en Chile, calificados como exportación por el Servicio Nacional de Aduanas)'),
  ('CL', 'exempt', 'exempt', 'Operación exenta del Impuesto al Valor Agregado (artículo 12 o 13 del D.L. N° 825, de 1974, según el caso).', '{}'::jsonb, 30, date '1970-01-01', null, 'Decreto Ley N° 825, arts. 12 y 13 — ventas, servicios, empresas e instituciones exentas del impuesto de este Título'),
  ('CL', 'reverse_charge', 'reverse_charge', 'El impuesto de este servicio lo declara y entera el beneficiario del servicio, contribuyente de este impuesto (artículo 11, letra e), del D.L. N° 825, de 1974).', '{}'::jsonb, 40, date '1970-01-01', null, 'Decreto Ley N° 825, art. 11, letra e) — es sujeto del impuesto «el beneficiario del servicio que sea contribuyente de este impuesto, siempre que la prestación sea realizada por un prestador domiciliado o residente en el extranjero»')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
